# Generated by GitHub Copilot
"""
Live ArUco detection viewer: MuJoCo native 3D window orbits around the cube
while offscreen rendering feeds the ArUco detector each frame.
Detection status is printed to the console in real time.

Usage:
    mjpython ARUCO/live_orbit_viewer.py

Controls:
    Close the viewer window to stop early.
    Wait DURATION seconds for automatic stop.
"""

import math
import os
import time
import xml.etree.ElementTree as ET

import cv2
import mujoco
import mujoco.viewer
import numpy as np


ARUCO_DIR  = os.path.dirname(os.path.abspath(__file__))
SCENE_PATH = os.path.join(ARUCO_DIR, "scene_box_aruco.xml")

OFF_WIDTH  = 640   # offscreen render width for detection (px)
OFF_HEIGHT = 480   # offscreen render height for detection (px)
DURATION   = 15.0  # seconds (0 = run until window closed)
RADIUS     = 0.50  # orbit distance from cube (m)
ELEVATION  = -25   # camera elevation angle (degrees, negative = looking down)
RPM        = 3   # rotations per minute


# Generated by GitHub Copilot
def load_cube_pos(scene_path):
    """Read cube center position from scene XML."""
    root = ET.parse(scene_path).getroot()
    body = root.find(".//worldbody/body[@name='object']")
    if body is None:
        raise ValueError("Cube body 'object' not found in scene XML")
    vals = [float(v) for v in body.get("pos", "0 0 0").split()]
    return np.array(vals, dtype=np.float64)


# Generated by GitHub Copilot
def build_detector():
    """Build an ArUco detector with sub-pixel corner refinement."""
    aruco_dict = cv2.aruco.getPredefinedDictionary(cv2.aruco.DICT_6X6_250)
    params = cv2.aruco.DetectorParameters()
    params.adaptiveThreshWinSizeMin  = 3
    params.adaptiveThreshWinSizeMax  = 31
    params.adaptiveThreshWinSizeStep = 4
    params.cornerRefinementMethod    = cv2.aruco.CORNER_REFINE_SUBPIX
    return cv2.aruco.ArucoDetector(aruco_dict, params)


# Generated by GitHub Copilot
def main():
    """Open MuJoCo native viewer, orbit camera, run ArUco detection offscreen."""
    model    = mujoco.MjModel.from_xml_path(SCENE_PATH)
    data     = mujoco.MjData(model)
    renderer = mujoco.Renderer(model, height=OFF_HEIGHT, width=OFF_WIDTH)

    cube_pos = load_cube_pos(SCENE_PATH)
    target   = cube_pos + np.array([0.0, 0.0, 0.02])

    # Intrinsics for the offscreen renderer
    fovy_off = 45.0  # degrees — matches default free camera fovy
    fy   = 0.5 * OFF_HEIGHT / np.tan(np.deg2rad(fovy_off) * 0.5)
    K    = np.array([[fy, 0, OFF_WIDTH / 2], [0, fy, OFF_HEIGHT / 2], [0, 0, 1]], dtype=np.float32)
    dist_coeffs = np.zeros((4, 1), dtype=np.float32)

    marker_size_m = 0.04
    half          = marker_size_m / 2.0
    marker_local  = np.array(
        [[-half, half, 0.0], [half, half, 0.0], [half, -half, 0.0], [-half, -half, 0.0]],
        dtype=np.float32,
    )

    detector = build_detector()
    omega    = 2.0 * math.pi * RPM / 60.0  # rad/s
    elev_rad = math.radians(ELEVATION)

    print(f"Live orbit — {DURATION:.0f}s at {RPM} RPM — close window to quit")
    print(f"Cube: {cube_pos}  |  detection at {OFF_WIDTH}×{OFF_HEIGHT}\n")

    with mujoco.viewer.launch_passive(model, data) as viewer:
        # Lock the viewer to a fixed lookat on the cube
        viewer.cam.lookat[:] = target
        viewer.cam.distance  = RADIUS * 1.8
        viewer.cam.elevation = ELEVATION

        t_start     = time.time()
        last_status = ""

        while viewer.is_running():
            t = time.time() - t_start
            if DURATION > 0 and t > DURATION:
                break

            # ── Orbit angle ──────────────────────────────────────────────
            theta            = omega * t
            viewer.cam.azimuth = math.degrees(theta) % 360

            # ── Compute explicit camera pose for offscreen renderer ───────
            sin_e = math.sin(elev_rad)
            cos_e = math.cos(elev_rad)
            cam_offset = np.array([
                RADIUS * cos_e * math.cos(theta),
                RADIUS * cos_e * math.sin(theta),
                RADIUS * sin_e,
            ])
            cam_pos = target + cam_offset

            # Attach a temporary free camera to the renderer
            free_cam             = mujoco.MjvCamera()
            free_cam.type        = mujoco.mjtCamera.mjCAMERA_FREE
            free_cam.lookat[:]   = target
            free_cam.distance    = RADIUS
            free_cam.azimuth     = math.degrees(theta) % 360
            free_cam.elevation   = ELEVATION

            mujoco.mj_forward(model, data)

            renderer.update_scene(data, camera=free_cam)
            frame_rgb = renderer.render().copy()
            frame_bgr = cv2.cvtColor(frame_rgb, cv2.COLOR_RGB2BGR)

            # ── ArUco detection ───────────────────────────────────────────
            gray            = cv2.cvtColor(frame_bgr, cv2.COLOR_BGR2GRAY)
            corners, ids, _ = detector.detectMarkers(gray)

            if ids is not None and len(ids) > 0:
                det_ids = ids.flatten().tolist()
                has_42  = 42 in det_ids
                if has_42:
                    idx42 = det_ids.index(42)
                    ok, rvec, tvec = cv2.solvePnP(
                        marker_local, corners[idx42][0], K, dist_coeffs,
                        flags=cv2.SOLVEPNP_ITERATIVE,
                    )
                    if ok:
                        tx, ty, tz = tvec.flatten()
                        status = (f"t={t:5.1f}s | ✓ DETECTED  "
                                  f"marker_cam=({tx:+.3f}, {ty:+.3f}, {tz:+.3f}) m")
                    else:
                        status = f"t={t:5.1f}s | ✓ detected but solvePnP failed"
                else:
                    status = f"t={t:5.1f}s | other marker(s) seen: {det_ids}"
            else:
                status = f"t={t:5.1f}s | ✗ no detection"

            if status != last_status:
                print(status)
                last_status = status

            viewer.sync()

    renderer.close()
    print("\nDone.")


if __name__ == "__main__":
    main()
